/**
 * UserDashboard — The core product experience after signup.
 * Shows: plan status, API keys, usage stats, quick start checklist, billing.
 *
 * Uses real tRPC procedures:
 *   - trpc.apiKeys.list / create / delete / regenerate
 *   - trpc.usage.stats
 *   - trpc.subscription.current / billingHistory
 *   - trpc.stripe.createCheckout / billingPortal
 */
import { useState } from "react";
import type { inferRouterOutputs } from "@trpc/server";
import type { AppRouter } from "../../../server/routers";
import { useAuth } from "@/_core/hooks/useAuth";
import { trpc } from "@/lib/trpc";
import { toast } from "sonner";
import { Link } from "wouter";
import {
  Key, BarChart3, CreditCard, Zap, Copy, Trash2, RefreshCw,
  Plus, CheckCircle2, Circle, ExternalLink, ChevronRight,
  Activity, Shield, Code2, BookOpen, ArrowUpRight, Eye, EyeOff,
  AlertCircle, Loader2
} from "lucide-react";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Progress } from "@/components/ui/progress";
import {
  Dialog, DialogContent, DialogDescription, DialogFooter,
  DialogHeader, DialogTitle, DialogTrigger
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";

const PLAN_COLORS: Record<string, string> = {
  free: "bg-slate-100 text-slate-700",
  developer: "bg-blue-100 text-blue-700",
  team: "bg-violet-100 text-violet-700",
  business: "bg-blue-100 text-blue-700",
  enterprise: "bg-emerald-100 text-emerald-700",
  builder: "bg-blue-100 text-blue-700",
  startup: "bg-violet-100 text-violet-700",
};

const PLAN_LIMITS: Record<string, number> = {
  free: 100,
  developer: 1000,
  team: 10000,
  business: 100000,
  enterprise: -1,
  builder: 15000,
  startup: 75000,
};

function QuickStartChecklist({ hasApiKey, hasUsage }: { hasApiKey: boolean; hasUsage: boolean }) {
  const steps = [
    { done: true, label: "Create your account", link: null },
    { done: hasApiKey, label: "Generate your first API key", link: "#api-keys" },
    { done: hasUsage, label: "Make your first governance check", link: "/docs/quickstart" },
    { done: false, label: "Integrate with your AI pipeline", link: "/docs" },
    { done: false, label: "Set up Slack alerts", link: "/settings/slack" },
  ];

  const completed = steps.filter(s => s.done).length;

  return (
    <Card className="border-border/50">
      <CardHeader className="pb-3">
        <div className="flex items-center justify-between">
          <CardTitle className="text-base font-semibold">Getting Started</CardTitle>
          <span className="text-xs text-muted-foreground">{completed}/{steps.length} complete</span>
        </div>
        <Progress value={(completed / steps.length) * 100} className="h-1.5" />
      </CardHeader>
      <CardContent className="space-y-2">
        {steps.map((step, i) => (
          <div key={i} className="flex items-center gap-3">
            {step.done
              ? <CheckCircle2 className="h-4 w-4 text-emerald-500 shrink-0" />
              : <Circle className="h-4 w-4 text-muted-foreground/40 shrink-0" />
            }
            {step.link && !step.done ? (
              <Link href={step.link} className="text-sm text-primary hover:underline flex items-center gap-1">
                {step.label} <ChevronRight className="h-3 w-3" />
              </Link>
            ) : (
              <span className={`text-sm ${step.done ? "text-muted-foreground line-through" : "text-foreground"}`}>
                {step.label}
              </span>
            )}
          </div>
        ))}
      </CardContent>
    </Card>
  );
}

/**
 * The list endpoint returns a projection of the key row, so every field is
 * optional on the wire. `id` is the one the card genuinely can't work without
 * (delete/regenerate address a key by it), so the list filters on it and the
 * card renders the remaining fields defensively.
 */
type ApiKeyListItem = inferRouterOutputs<AppRouter>["apiKeys"]["list"][number];
type IdentifiedApiKey = ApiKeyListItem & { id: number };

function hasId(apiKey: ApiKeyListItem): apiKey is IdentifiedApiKey {
  return typeof apiKey.id === "number";
}

function ApiKeyCard({ apiKey, onDelete, onRegenerate }: {
  apiKey: IdentifiedApiKey;
  onDelete: (id: number) => void;
  onRegenerate: (id: number) => void;
}) {
  const [showFull, setShowFull] = useState(false);
  const keyPrefix = apiKey.keyPrefix ?? "";
  const displayKey = showFull ? `${keyPrefix}${"•".repeat(32)}` : `${keyPrefix}••••••••`;

  return (
    <div className="flex items-center justify-between p-3 rounded-lg border border-border/50 bg-muted/20 hover:bg-muted/40 transition-colors">
      <div className="flex items-center gap-3 min-w-0">
        <Key className="h-4 w-4 text-muted-foreground shrink-0" />
        <div className="min-w-0">
          <div className="flex items-center gap-2">
            <span className="text-sm font-medium truncate">{apiKey.name || "Unnamed key"}</span>
            <Badge variant={apiKey.isActive ? "default" : "secondary"} className="text-xs h-4">
              {apiKey.isActive ? "active" : "inactive"}
            </Badge>
          </div>
          <div className="flex items-center gap-2 mt-0.5">
            <code className="text-xs text-muted-foreground font-mono">{displayKey}</code>
            <button onClick={() => setShowFull(!showFull)} className="text-muted-foreground hover:text-foreground">
              {showFull ? <EyeOff className="h-3 w-3" /> : <Eye className="h-3 w-3" />}
            </button>
          </div>
          <p className="text-xs text-muted-foreground mt-0.5">
            {apiKey.createdAt ? `Created ${new Date(apiKey.createdAt).toLocaleDateString()}` : "Created —"}
            {apiKey.lastUsedAt && ` · Last used ${new Date(apiKey.lastUsedAt).toLocaleDateString()}`}
          </p>
        </div>
      </div>
      <div className="flex items-center gap-1 shrink-0">
        <Button
          variant="ghost" size="icon" className="h-7 w-7"
          onClick={() => { navigator.clipboard.writeText(keyPrefix); toast.success("Key prefix copied"); }}
        >
          <Copy className="h-3.5 w-3.5" />
        </Button>
        <Button
          variant="ghost" size="icon" className="h-7 w-7"
          onClick={() => onRegenerate(apiKey.id)}
        >
          <RefreshCw className="h-3.5 w-3.5" />
        </Button>
        <Button
          variant="ghost" size="icon" className="h-7 w-7 text-destructive hover:text-destructive"
          onClick={() => onDelete(apiKey.id)}
        >
          <Trash2 className="h-3.5 w-3.5" />
        </Button>
      </div>
    </div>
  );
}

/**
 * ApiKeyRevealDialog — the ONE reliable moment a user can see their full key.
 *
 * The server only stores a hash, so the plaintext is unrecoverable after this.
 * A transient toast was too easy to miss; this is a persistent dialog with a
 * copy button, a shown-once warning, and a selectable monospace field.
 */
function ApiKeyRevealDialog({ apiKey, onClose }: { apiKey: string | null; onClose: () => void }) {
  const [copied, setCopied] = useState(false);

  const handleCopy = async () => {
    if (!apiKey) return;
    try {
      await navigator.clipboard.writeText(apiKey);
      setCopied(true);
      toast.success("Copied to clipboard");
      setTimeout(() => setCopied(false), 2000);
    } catch {
      toast.error("Couldn't copy — select the key and copy it manually.");
    }
  };

  const close = () => {
    setCopied(false);
    onClose();
  };

  return (
    <Dialog open={!!apiKey} onOpenChange={(open) => { if (!open) close(); }}>
      <DialogContent onEscapeKeyDown={(e) => e.preventDefault()}>
        <DialogHeader>
          <DialogTitle>Your new API key</DialogTitle>
          <DialogDescription>
            Copy your key now and store it somewhere safe.
          </DialogDescription>
        </DialogHeader>

        <div className="flex items-start gap-2 rounded-md border border-blue-200 bg-blue-50 p-3">
          <AlertCircle className="h-4 w-4 text-blue-600 mt-0.5 shrink-0" />
          <p className="text-xs font-medium text-blue-700">
            Save this key now — you won't be able to see it again. We only store a
            hashed copy, so it can't be recovered later.
          </p>
        </div>

        <div className="flex items-center gap-2">
          <Input
            readOnly
            aria-label="Your new API key"
            value={apiKey ?? ""}
            className="font-mono text-xs"
            onFocus={(e) => e.currentTarget.select()}
          />
          <Button
            type="button" variant="outline" size="icon"
            aria-label="Copy API key"
            onClick={handleCopy}
          >
            {copied ? <CheckCircle2 className="h-4 w-4 text-emerald-500" /> : <Copy className="h-4 w-4" />}
          </Button>
        </div>

        <DialogFooter>
          <Button onClick={close}>Done</Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

