/**
 * UserDashboard — API-key reveal contract test.
 *
 * Runs in the `client-node` vitest project (node env, no DOM). It reads the
 * source of the dashboard and asserts the packet's "done" invariants for the
 * customer-blocking bug: creating or regenerating a key must reveal the full
 * plaintext in a PERSISTENT, copyable dialog (not a transient toast that's
 * easily missed), because the server only stores a hash and the plaintext is
 * unrecoverable afterward. The list stays secure (prefix only), and the null
 * data case (regenerate can return null) is guarded.
 */
import { describe, it, expect } from "vitest";
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

function read(rel: string): string {
  try {
    return readFileSync(fileURLToPath(new URL(rel, import.meta.url)), "utf8");
  } catch {
    return "";
  }
}

const dash = read("./UserDashboard.tsx");

describe("UserDashboard — persistent API-key reveal", () => {
  it("reveals the new key in a persistent Dialog driven by revealed-key state", () => {
    expect(dash).toMatch(/ApiKeyRevealDialog/);
    expect(dash).toMatch(/revealedKey/);
    expect(dash).toMatch(/setRevealedKey/);
    // The reveal dialog is mounted and keyed off the full plaintext key.
    expect(dash).toMatch(/<ApiKeyRevealDialog[\s\S]*?apiKey=\{revealedKey\}/);
  });

  it("stops dumping the plaintext key into a transient toast description", () => {
    // Split the "$" from "{" so this literal isn't itself a template expression
    // (no-template-curly-in-string) while still asserting the old toast text is gone.
    expect(dash).not.toContain("Key: $" + "{data.key}");
    expect(dash).not.toContain("New key: $" + "{data.key}");
    // Create opens the reveal with the full key instead.
    expect(dash).toMatch(/setRevealedKey\(data\.key\)/);
  });

  it("guards the null data case on BOTH create and regenerate", () => {
    const guards = dash.match(/if \(data\)/g) ?? [];
    expect(guards.length).toBeGreaterThanOrEqual(2);
  });

  it("shows the shown-once warning verbatim", () => {
    expect(dash).toContain("Save this key now");
    expect(dash).toContain("you won't be able to see it again");
  });

  it("renders the key in a monospace, selectable, read-only field", () => {
    expect(dash).toMatch(/font-mono/);
    expect(dash).toMatch(/readOnly/);
    expect(dash).toMatch(/\.select\(\)/);
  });

  it("copies the full key to the clipboard with a Copied confirmation", () => {
    expect(dash).toMatch(/navigator\.clipboard\.writeText/);
    expect(dash).toMatch(/Copied/);
    expect(dash).toMatch(/setCopied/);
  });

  it("keeps the list secure: cards still render only the key prefix", () => {
    expect(dash).toMatch(/apiKey\.keyPrefix/);
  });

  it("never embeds the forbidden model id", () => {
    const forbidden = ["claude", "opus", "4", "8"].join("-");
    expect(dash).not.toContain(forbidden);
  });
});
